def decimal_total(amounts):
    parsed = []
    precision = 2
    for original in amounts:
        value = original.strip()
        value = re.sub(r'^(?:USD\s*|\$\s*)', '', value, flags=re.I)
        value = re.sub(r'\s*USD$', '', value, flags=re.I)
        negative = value.startswith('(') and value.endswith(')')
        if negative:
            value = value[1:-1]
        if not re.fullmatch(r'[+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?', value):
            raise ValueError('Ambiguous or non-USD amount: ' + original)
        number = Decimal(value.replace(',', ''))
        if negative:
            number = -number
        precision = max(precision, -number.as_tuple().exponent)
        parsed.append(number)
    with localcontext() as context:
        context.prec = max(80, sum(len(str(number)) for number in parsed) + 10)
        total = sum(parsed, Decimal(0))
        return format(total, f'.{precision}f')


def searchable(value):
    fragments = []
    def visit(item):
        if isinstance(item, dict):
            for child in item.values():
                visit(child)
        elif isinstance(item, list):
            for child in item:
                visit(child)
        else:
            text = str(item)
            fragments.append(text)
            try:
                decoded = json.loads(text)
                if isinstance(decoded, (dict, list)):
                    visit(decoded)
            except (ValueError, TypeError):
                pass
            if len(text) >= 16 and re.fullmatch(r'[A-Za-z0-9_+/=-]+', text):
                try:
                    decoded = base64.urlsafe_b64decode(text + '=' * (-len(text) % 4)).decode('utf-8')
                    fragments.append(decoded)
                except (ValueError, UnicodeError):
                    pass
    visit(value)
    return '\n'.join(fragments)


