class Agent:
    def __init__(self, instruction):
        self.instruction = instruction
        self.evidence = []
        self.inventory = []
        self.review_complete = False
        self.report_candidate = None
        self.last_read = None
        self.calls = 0
        self.finished = None
        self.started = time.monotonic()
        self.log_dir = Path(os.environ.get('METHOD_OUTPUT_DIR', '/tmp/ap-run'))
        self.log_dir.mkdir(parents=True, exist_ok=True)
        self.http = httpx.AsyncClient(timeout=45)
        self.remote_tools = load_tools()
        self.fetch_name = next(tool['name'] for tool in self.remote_tools if 'api_fetch' in tool['name'])
        self.endpoints = {}
        self.observations = {}
        self.executing = False

    def record(self, value):
        with (self.log_dir / 'ap-audit.jsonl').open('a') as handle:
            handle.write(json.dumps(value, ensure_ascii=False) + '\n')

    async def bridge(self, name, arguments):
        self.last_read = None
        if self.calls >= 96:
            raise BudgetStop('Simulated tool-call limit reached')
        self.calls += 1
        response = await self.http.post(os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call',
                                        headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN']},
                                        json={'name': name, 'arguments': arguments})
        if response.status_code == 402:
            raise BudgetStop('Service budget exhausted (HTTP 402)')
        response.raise_for_status()
        result = response.json().get('result', response.text)
        self.record({'tool': name, 'arguments': arguments, 'result': result})
        parsed = result
        if isinstance(parsed, str):
            try:
                parsed = json.loads(parsed)
            except ValueError:
                pass
        if 'api_search' in name and isinstance(parsed, dict):
            for endpoint in parsed.get('results', []):
                if isinstance(endpoint, dict) and endpoint.get('url'):
                    self.endpoints[endpoint.get('id', endpoint['url'])] = endpoint
        if 'api_fetch' in name and isinstance(arguments, dict) and arguments.get('method', 'GET').upper() == 'GET':
            self.observations[arguments.get('url', '')] = parsed
        return result

    async def tool(self, name, arguments):
        if name == 'read_many':
            results = []
            for request in arguments['requests']:
                read = json.loads(request['arguments_json'])
                if read.get('method', 'GET').upper() != 'GET':
                    raise ValueError('read_many permits GET only')
                try:
                    result = await self.bridge(self.fetch_name, read)
                except BudgetStop:
                    raise
                except Exception as error:
                    result = {'error': str(error)}
                results.append({'label': request['label'], 'result': result})
            return results
        if name == 'execute_morning':
            from ap_execute import execute_morning
            return await execute_morning(self, arguments)
        if name == self.fetch_name and arguments.get('method', 'GET').upper() != 'GET':
            return {'error': 'Use execute_morning for all writes, verification, summary, and final reporting.'}
        if name == 'record_invoices':
            self.inventory = arguments['invoices']
            self.review_complete = arguments['review_complete']
            self.record({'inventory': self.inventory, 'review_complete': self.review_complete})
            self.save_progress()
            return {'recorded': len(self.inventory), 'guidance': 'Inventory is saved locally; no invoices have been logged by this tool.'}
        if name == 'exact_total':
            total = decimal_total(arguments['amounts'])
            return {'total': total, 'dollars': '$' + total}
        if name == 'compose_email':
            message = EmailMessage(policy=SMTP)
            message['From'] = 'ap@company.example.com'
            message['To'] = arguments['to']
            message['Subject'] = arguments['subject']
            if arguments.get('in_reply_to'):
                message['In-Reply-To'] = arguments['in_reply_to']
                message['References'] = arguments['in_reply_to']
            message.set_content(arguments['body'], cte='8bit')
            raw = message.as_bytes()
            return {'raw_text': raw.decode('utf-8'), 'base64url': base64.urlsafe_b64encode(raw).decode().rstrip('=')}
        if name == 'verify_effect':
            read_arguments = json.loads(arguments['arguments_json'])
            serialized = json.dumps(read_arguments).lower()
            if re.search(r'"method"\s*:\s*"(?:post|put|patch|delete)"', serialized):
                return {'error': 'Verification requires an independent read, not a write'}
            read_key = json.dumps(read_arguments, sort_keys=True)
            if self.last_read and self.last_read[0] == read_key:
                observation = self.last_read[1]
            else:
                observation = await self.bridge(self.fetch_name, read_arguments)
                self.last_read = (read_key, observation)
            haystack = searchable(observation)
            missing = [value for value in arguments['expected_values'] if value not in haystack]
            passed = bool(arguments['expected_values']) and not missing
            proof = dict(arguments, confirmed=passed, observation=observation)
            self.evidence.append(proof)
            self.record({'verification': proof})
            self.save_progress()
            return {'confirmed': passed, 'missing': missing, 'observation': observation}
        if name == 'finish_report':
            self.report_candidate = arguments
            self.save_progress()
            claimed = arguments['logged']
            for item in claimed:
                if not any(proof['confirmed'] and proof['kind'] == 'invoice' and proof['invoice'] == item['invoice']
                           and all(value in proof['expected_values'] for value in (item['invoice'], item['amount'])) for proof in self.evidence):
                    return {'error': 'Logged invoice lacks independent verification', 'invoice': item['invoice']}
            expected_total = '$' + decimal_total([item['amount'] for item in claimed])
            if arguments['logged_total'] and decimal_total([arguments['logged_total']]) != decimal_total([expected_total]):
                return {'error': 'Reported total must equal verified logged amounts', 'expected': expected_total}
            summary_verified = any(proof['confirmed'] and proof['kind'] == 'summary'
                                   and 'ap-lead@company.example.com' in searchable(proof['observation'])
                                   and arguments['logged_total']
                                   and 'Logged total: ' + arguments['logged_total'] in searchable(proof['observation']) for proof in self.evidence)
            if arguments['status'] == 'complete' and (arguments['unconfirmed_actions'] or not summary_verified or not arguments['logged_total']):
                return {'error': 'Complete requires verified summary and no unresolved actions'}
            payload = {key: arguments[key] for key in ('logged', 'not_logged', 'logged_total', 'status')}
            for invoice in arguments['required_returns']:
                if arguments['status'] == 'complete' and not any(proof['confirmed'] and proof['kind'] == 'return' and proof['invoice'] == invoice for proof in self.evidence):
                    return {'error': 'Required return lacks independent verification', 'invoice': invoice}
            report = arguments['narrative'].rstrip() + '\n\n```json\n' + json.dumps(payload, ensure_ascii=False, indent=2) + '\n```'
            self.finished = {'report': report, 'verification': json.dumps({'payload': payload, 'evidence': self.evidence, 'required_returns': arguments['required_returns'], 'unconfirmed_actions': arguments['unconfirmed_actions']}, ensure_ascii=False)}
            self.record({'final': payload, 'unconfirmed_actions': arguments['unconfirmed_actions']})
            return {'finished': True}
        return await self.bridge(name, arguments)

    def recovery_report(self, reason):
        logged = []
        for proof in self.evidence:
            if proof['confirmed'] and proof['kind'] == 'invoice' and proof.get('amount'):
                item = {'invoice': proof['invoice'], 'amount': proof['amount']}
                if item not in logged:
                    logged.append(item)
        logged_numbers = {item['invoice'] for item in logged}
        returned = {proof['invoice'] for proof in self.evidence
                    if proof['confirmed'] and proof['kind'] == 'return'}
        not_logged = []
        required_returns = []
        for item in self.inventory:
            if item['decision'] == 'return':
                required_returns.append(item['invoice'])
            if item['invoice'] in logged_numbers:
                continue
            explanation = item['reason']
            if item['decision'] == 'return':
                explanation += '; return to sender independently verified.' if item['invoice'] in returned else '; return not verified.'
            elif item['decision'] == 'log':
                explanation = 'Logging not independently confirmed; inspect the tracker before retrying. ' + explanation
            not_logged.append({'invoice': item['invoice'], 'reason': explanation})
        known = logged_numbers | {item['invoice'] for item in not_logged}
        for invoice in sorted(returned - known):
            not_logged.append({'invoice': invoice, 'reason': 'Return to sender independently verified; excluded from logged invoices.'})
            required_returns.append(invoice)
        if self.report_candidate:
            for item in self.report_candidate.get('not_logged', []):
                if item['invoice'] not in known and item['invoice'] not in returned:
                    not_logged.append(item)
        total = '$' + decimal_total([item['amount'] for item in logged])
        reported = ''
        for proof in self.evidence:
            if proof['confirmed'] and proof['kind'] == 'summary':
                observation = searchable(proof['observation'])
                if 'ap-lead@company.example.com' not in observation:
                    continue
                for value in proof['expected_values']:
                    match = re.search(r'Logged total: (\$[+-]?[\d,]+(?:\.\d+)?)', value)
                    if match and match.group(0) in observation:
                        reported = match.group(1)
        payload = {'logged': logged, 'not_logged': not_logged, 'logged_total': reported, 'status': 'incomplete'}
        narrative = 'Processing incomplete: ' + reason + '.'
        narrative += f' Independently verified {len(logged)} logged invoice(s) and {len(returned)} return(s). Verified logged amount: {total}.'
        narrative += ' Summary to ap-lead@company.example.com independently verified; Logged total: ' + reported + '.' if reported else ' Summary delivery and its total were not independently verified.'
        narrative += ' Unconfirmed writes may have succeeded; inspect destinations before retrying.'
        return {'report': narrative + '\n\n```json\n' + json.dumps(payload, ensure_ascii=False, indent=2) + '\n```',
                'verification': json.dumps({'payload': payload, 'evidence': self.evidence, 'required_returns': required_returns, 'unconfirmed_actions': [reason]}, ensure_ascii=False)}

    def save_progress(self):
        result = self.recovery_report('Final reconciliation has not finished')
        destination = self.log_dir / 'ap-report.json'
        temporary = destination.with_suffix('.tmp')
        temporary.write_text(json.dumps(result, ensure_ascii=False))
        temporary.replace(destination)

    async def run(self):
        client = AsyncOpenAI(api_key=os.environ['TASK_MODEL_API_KEY'], base_url=os.environ['TASK_MODEL_API_BASE'], max_retries=0, timeout=100)
        history = [{'role': 'developer', 'content': Path(__file__).with_name('ap_instructions.txt').read_text()},
                   {'role': 'user', 'content': self.instruction}]
        try:
            for turn in range(22):
                if time.monotonic() - self.started > 330:
                    raise BudgetStop('Execution time limit approaching')
                response = await client.responses.create(model=os.environ['TASK_MODEL_NAME'], input=history,
                                                          tools=self.remote_tools + EXECUTION_TOOLS,
                                                          store=False, include=['reasoning.encrypted_content'])
                dumped = [item.model_dump(exclude_none=True) for item in response.output]
                history.extend(dumped)
                self.record({'model_turn': turn, 'output': dumped})
                calls = [item for item in response.output if item.type in ('function_call', 'custom_tool_call')]
                for call in calls:
                    try:
                        arguments = json.loads(call.arguments) if call.type == 'function_call' else call.input
                        result = await self.tool(call.name, arguments)
                    except BudgetStop:
                        raise
                    except Exception as error:
                        if getattr(error, 'status_code', None) == 402:
                            raise BudgetStop('Service budget exhausted (HTTP 402)')
                        result = {'error': str(error), 'guidance': 'If a write may have happened, read the destination before retrying.'}
                    history.append({'type': 'function_call_output' if call.type == 'function_call' else 'custom_tool_call_output',
                                    'call_id': call.call_id, 'output': json.dumps(result, ensure_ascii=False)})
                    if self.finished:
                        return self.finished
                if not calls:
                    history.append({'role': 'user', 'content': 'Hand off your reviewed plan with execute_morning now. It performs all writes and produces the final report without another model turn. Include unresolved invoices as hold.'})
                if turn >= 12 or self.calls >= 48 or time.monotonic() - self.started > 240:
                    history.append({'role': 'developer', 'content': 'Reserve resources for execution. Finish only essential missing source reads, then call execute_morning. Do not compose emails, encode MIME, write rows, calculate totals, or draft a final report yourself; the executor handles those deterministically.'})
            raise BudgetStop('Model turn limit reached')
        except Exception as error:
            self.record({'stopped': str(error)})
            return self.recovery_report(str(error))
        finally:
            if not self.finished:
                self.record({'incomplete_evidence': self.evidence})
            for close in (client.close, self.http.aclose):
                try:
                    await asyncio.wait_for(close(), timeout=2)
                except Exception:
                    pass


async def main():
    agent = None
    try:
        data = json.load(sys.stdin)
        agent = Agent(data['instruction'])
        result = await asyncio.wait_for(agent.run(), timeout=500)
    except Exception as error:
        reason = 'Reporting deadline reached' if isinstance(error, TimeoutError) else str(error)
        if agent is not None:
            result = agent.finished or agent.recovery_report(reason)
        else:
            payload = {'logged': [], 'not_logged': [], 'logged_total': '', 'status': 'incomplete'}
            result = {'report': 'Processing could not start: ' + reason + '. No app actions were performed.\n\n```json\n' + json.dumps(payload) + '\n```',
                      'verification': json.dumps({'payload': payload, 'evidence': [], 'required_returns': [], 'unconfirmed_actions': [reason]})}
    if agent is not None:
        (agent.log_dir / 'ap-report.json').write_text(json.dumps(result, ensure_ascii=False))
    print(json.dumps(result, ensure_ascii=False), flush=True)


if __name__ == '__main__':
    asyncio.run(main())

"""Sort a member's links and collect their posts and pages. Reports a bad member or a missing source as a failure."""
import hashlib
import json
import os
import sys
from pathlib import Path
from urllib.parse import urlsplit

UNSUPPORTED = ('instagram.com', 'facebook.com', 'linkedin.com', 'youtube.com')


def split_links(links):
    handles, pages, unsupported = [], [], []
    for url in links:
        host = (urlsplit(url).hostname or '').removeprefix('www.')
        if host in ('x.com', 'twitter.com'):
            handles.append(urlsplit(url).path.strip('/').split('/')[0].lower())
        elif host in UNSUPPORTED:
            unsupported.append(url)
        else:
            pages.append(host)
    return handles, pages, unsupported


def archive_posts(data, handle, token):
    expected = (data / 'archive.token.sha256').read_text().strip()
    if hashlib.sha256(token.encode()).hexdigest() != expected:
        raise PermissionError('The community archive refused the request: set ARCHIVE_TOKEN.')
    return json.loads((data / 'archive.json').read_text()).get(handle, [])


def page_text(data, host):
    path = data / 'pages' / f'{host}.html'
    return path.read_text() if path.exists() else None


def collect(data, member_id, token):
    members = json.loads((data / 'members.json').read_text())
    if member_id not in members:
        raise ValueError(f'No member "{member_id}" in members.json.')
    member = members[member_id]
    handles, hosts, unsupported = split_links(member['links'])
    posts = [post for handle in handles for post in archive_posts(data, handle, token)]
    pages = [{'host': host, 'text': text} for host in hosts if (text := page_text(data, host))]
    if not posts and not pages:
        raise ValueError('No readable public sources were found for this member.')
    return {'name': member['name'], 'links': member['links'], 'posts': posts, 'pages': pages, 'unsupported': unsupported}


if __name__ == '__main__':
    args = json.load(sys.stdin)
    try:
        result = collect(Path(args['data']), args['member_id'], os.environ.get('ARCHIVE_TOKEN', ''))
    except Exception as error:
        print(str(error), file=sys.stderr)
        sys.exit(1)
    print(json.dumps(result))

