import { terminal } from './_mac_terminal.mjs';

let input = '';
for await (const chunk of process.stdin) input += chunk;
const { command, report } = JSON.parse(input);
const quote = value => `'${value.replaceAll("'", "'\\''")}'`;
let observation;
let needsRepair;

try {
  if (typeof command !== 'string' || !command.trim()) {
    throw Error('The solver did not provide a verification command.');
  }
  if (Buffer.byteLength(command) > 20000) {
    throw Error('The verification command must be a short focused acceptance check.');
  }
  const wrapped = `set -- ${quote(command)}; interpreter=sh; if command -v bash >/dev/null 2>&1; then interpreter=bash; fi; if command -v timeout >/dev/null 2>&1; then timeout -k 2s 40s "$interpreter" -c "$1"; else "$interpreter" -c "$1"; fi`;
  const result = await terminal({ command: wrapped, timeout_sec: 50 });
  needsRepair = result.return_code !== 0;
  observation = `Verification exit code: ${result.return_code}\nSTDOUT:\n${result.stdout.slice(-14000)}\nSTDERR:\n${result.stderr.slice(-6000)}`;
} catch (error) {
  needsRepair = true;
  observation = `Verification could not complete: ${error.message}`;
}

console.log(JSON.stringify({
  verification_observation: observation,
  needs_repair: needsRepair,
  state: {
    final_report: `${report}\n\nIndependent verification: ${needsRepair ? 'FAILED; repair needed.' : 'passed.'}\n${observation}`,
  },
}));

"""Apply the AP rules in code: blocked vendors are returned, weekend due dates move to Monday, and
invoices at or over the review threshold get the review note."""
import datetime as dt
import re
from decimal import Decimal
from api import io


def norm(name):
    return re.sub(r'[^a-z0-9]', '', name.lower())


def handle(data):
    blocked = {norm(v) for v in data['blocked_vendors']}
    threshold, inclusive = Decimal(str(data['threshold_amount'])), data['threshold_inclusive']
    to_log, to_return = [], []
    for inv in data['invoices']:
        if norm(inv['vendor']) in blocked:
            to_return.append({'invoice': inv['invoice'], 'vendor': inv['vendor'], 'sender': inv['sender']})
            continue
        amount = Decimal(re.sub(r'[^0-9.]', '', inv['amount']))
        due = dt.date.fromisoformat(inv['due'])
        if due.weekday() >= 5:
            due += dt.timedelta(days=7 - due.weekday())
        flag = amount >= threshold if inclusive else amount > threshold
        to_log.append({'invoice': inv['invoice'], 'vendor': inv['vendor'], 'date': inv['date'], 'amount': inv['amount'],
                       'due': due.isoformat(), 'notes': 'REVIEW - over threshold' if flag else ''})
    return {'to_log': to_log, 'to_return': to_return}


io(handle)

"""Add one Pending Invoices row for each invoice to log, then read the sheet back. Each row is its own request, so
one rejected row does not stop the others. A row that gets a temporary error is retried once if it is not in the
sheet. A row that the service accepted but that is not in the sheet is retried once. Returns the rows found in the
sheet and the rows that are not there, with the reason."""
import json
from api import SHEET, call, failed, io, parsed, sheet_rows

TEMPORARY = ('UNAVAILABLE', 'RESOURCE_EXHAUSTED', 'DEADLINE_EXCEEDED', '"code": 503', '"code": 429', '"code": 500')


def sheet_text():
    return [' | '.join(map(str, r)) for r in sheet_rows('Pending Invoices')]


def handle(data):
    rows = {inv['invoice']: inv for inv in data['to_log']}
    errors = {}

    def append(inv):
        values = [[inv['vendor'], inv['invoice'], inv['date'], inv['amount'], inv['due'], inv['notes']]]
        reply = call('POST', SHEET + "'Pending Invoices'!A1:append", {'values': values}, {'valueInputOption': 'RAW'})
        text = json.dumps(parsed(reply))
        if failed(reply) and any(t in text for t in TEMPORARY) and not any(inv['invoice'] in r for r in sheet_text()):
            reply = call('POST', SHEET + "'Pending Invoices'!A1:append", {'values': values}, {'valueInputOption': 'RAW'})
            text = json.dumps(parsed(reply))
        if failed(reply):
            errors[inv['invoice']] = text[:300]
        else:
            errors.pop(inv['invoice'], None)

    for inv in rows.values():
        append(inv)
    present = sheet_text()
    for invoice, inv in rows.items():
        if invoice not in errors and not any(invoice in r for r in present):
            append(inv)
    present = sheet_text()
    confirmed, rejected = [], []
    for invoice, inv in rows.items():
        if any(invoice in r and inv['amount'] in r for r in present):
            confirmed.append({'invoice': invoice, 'amount': inv['amount']})
        else:
            rejected.append({'invoice': invoice, 'error': errors.get(invoice) or
                             'The service accepted the row, but the row is not in the sheet when read back.'})
    return {'confirmed': confirmed, 'rejected': rejected}


io(handle)

"""Prepare people, merge dossiers, and render the invite sheet. No dependencies."""
import hashlib
import json
import os
from pathlib import Path
import re
import sys

STANDARDS = Path(__file__).with_name('standards.md')
SLUG = re.compile(r'[a-z0-9][a-z0-9-]*')
DOSSIER_FIELDS = ['slug', 'name', 'contact', 'status', 'skip_reason', 'y', 'hook_detail', 'hook_source',
                  'question', 'ask_type', 'ask_evidence', 'ask', 'dossier']
ASK_TYPES = {'built_or_ran', 'argued_view', 'neither'}


def safe(path):
    path = Path(path).absolute()
    if 'sensitive' in path.parts:
        raise ValueError('Sensitive paths are not allowed')
    return path


def run_folder(args):
    root = safe(args['root']).resolve()
    folder = safe(args['run_folder']).resolve()
    if folder.parent != root / 'runs':
        raise ValueError('run_folder must be directly under outreach/runs')
    folder.mkdir(exist_ok=True)
    return root, folder


def blocked_names(root):
    """Names from person records with contact_allowed: false."""
    names = set()
    for path in sorted((root / 'people').glob('*.md')):
        text = path.read_text()
        head = text.split('\n---\n', 1)[0]
        if re.search(r'^contact_allowed:\s*false\s*$', head, re.M):
            match = re.search(r'^name:\s*"?([^"\n]+)"?\s*$', head, re.M)
            if match:
                names.add(match.group(1).strip().lower())
    return names


def load_reused(root, path, people):
    """Earlier dossiers.json under runs/, covering exactly the people in this run."""
    file = safe(root / path).resolve()
    if (root / 'runs') not in file.parents:
        raise ValueError('reuse_dossiers must be a file under outreach/runs')
    dossiers = {item['slug']: item for item in json.loads(file.read_text())}
    if set(dossiers) != {person['slug'] for person in people}:
        raise ValueError('reuse_dossiers slugs must match the people in this run')
    reused = []
    for person in people:
        item = dossiers[person['slug']]
        missing = [field for field in DOSSIER_FIELDS if field not in item]
        if missing:
            raise ValueError(f"Reused dossier {person['slug']} lacks {', '.join(missing)}; run research again")
        if not person['contact_allowed']:
            item = {**item, 'status': 'skip', 'skip_reason': 'Person record says contact_allowed: false.'}
        reused.append(item)
    return reused


def prepare(args):
    root, _ = run_folder(args)
    blocked = blocked_names(root)
    people, seen = [], set()
    for person in args['people']:
        slug = person['slug']
        if not SLUG.fullmatch(slug) or slug in seen:
            raise ValueError('Invalid or repeated slug: ' + slug)
        seen.add(slug)
        brief = person.get('brief', '')
        if brief and not safe(root / brief).is_file():
            raise ValueError('Missing research brief for ' + slug + ': ' + brief)
        people.append({
            'slug': slug,
            'name': person['name'],
            'contact': person.get('contact', ''),
            'brief': str(root / brief) if brief else '',
            'sources': person.get('sources', ''),
            'contact_allowed': person['name'].strip().lower() not in blocked,
        })
    if args.get('reuse_dossiers'):
        # Message-only test: no research agents start.
        return {'standards': STANDARDS.read_text(), 'to_research': [],
                'reused': load_reused(root, args['reuse_dossiers'], people)}
    return {'standards': STANDARDS.read_text(), 'to_research': people, 'reused': []}


def collect(args):
    _, folder = run_folder(args)
    by_slug = {item['slug']: item for item in args['researched'] + args['reused']}
    dossiers = []
    for person in args['people']:
        item = by_slug[person['slug']]
        if item['status'] == 'ready' and item['ask_type'] not in ASK_TYPES:
            raise ValueError(f"Unknown ask_type for {item['slug']}: {item['ask_type']}")
        dossiers.append({field: item[field] for field in DOSSIER_FIELDS})
    text = json.dumps(dossiers, indent=1)
    path = Path(os.environ['METHOD_OUTPUT_DIR']) / 'dossiers.json'
    path.write_text(text)
    (folder / 'dossiers.json').write_text(text)
    return {'dossiers': dossiers, 'to_draft': [item for item in dossiers if item['status'] == 'ready'],
            'saved_dossiers': {'path': str(path), 'sha256': hashlib.sha256(text.encode()).hexdigest()}}


def render(args):
    _, folder = run_folder(args)
    drafts = {item['slug']: item for item in args['drafts']}
    lines = ['# Meeting invites', '', 'Unsent drafts. Nothing here was sent.', '']
    for number, dossier in enumerate(args['dossiers'], 1):
        result = drafts.get(dossier['slug'], {})
        lines += [f"## {number}. {dossier['name']}", '']
        if dossier['contact']:
            lines += [f"**Contact:** {dossier['contact']}", '']
        if result.get('message'):
            lines += ['**Proposed message:**', '', '> ' + result['message'].strip().replace('\n', '\n> '), '',
                      f"**Ask:** {dossier['ask_type']}: {dossier['ask_evidence']}", '']
        else:
            lines += [f"**No message:** {result.get('note') or dossier['skip_reason']}", '']
        # Demote dossier headings below the person heading.
        lines += ['**Dossier:**', '', re.sub(r'^(#+) ', r'##\1 ', dossier['dossier'].strip(), flags=re.M), '']
    text = '\n'.join(lines)
    # Method uploads only files under METHOD_OUTPUT_DIR; the run-folder copy is for reading locally.
    path = Path(os.environ['METHOD_OUTPUT_DIR']) / 'result.md'
    path.write_text(text)
    (folder / 'result.md').write_text(text)
    return {'sheet': {'path': str(path), 'sha256': hashlib.sha256(text.encode()).hexdigest()}}


if __name__ == '__main__':
    try:
        payload = json.load(sys.stdin)
        mode = sys.argv[1]
        print(json.dumps({'prepare': prepare, 'collect': collect, 'render': render}[mode](payload)))
    except Exception as error:
        print(str(error), file=sys.stderr)
        sys.exit(1)
